import{_ as n,o as t,c as s,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0058 — Clôture d'une organisation par une commande d'exploitation","description":"Extrait de docs/adr/0058-cloture-d-une-organisation.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0058 — Clôture d'une organisation par une commande d'exploitation","description":"Extrait de docs/adr/0058-cloture-d-une-organisation.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0058-cloture-d-une-organisation.md","filePath":"developpeurs/adr/0058-cloture-d-une-organisation.md"}`),a={name:"developpeurs/adr/0058-cloture-d-une-organisation.md"};function i(r,e,c,d,l,u){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0058--clôture-dune-organisation-par-une-commande-dexploitation" tabindex="-1">ADR-0058 — Clôture d&#39;une organisation par une commande d&#39;exploitation <a class="header-anchor" href="#adr-0058--clôture-dune-organisation-par-une-commande-dexploitation" aria-label="Permalink to &quot;ADR-0058 — Clôture d&#39;une organisation par une commande d&#39;exploitation {#adr-0058--clôture-dune-organisation-par-une-commande-dexploitation}&quot;">​</a></h1><p><strong>Date :</strong> 28 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat RGPD-7 <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a>, écart reconnu dans ses conséquences négatives (« Supprimer une organisation efface ses lignes <code>media_assets</code> en cascade, mais laisse les octets sur le disque. C&#39;est le même écart que pour les fichiers personnels (ADR-0038). ») et son action « Effacer les octets des médias à la suppression d&#39;une organisation »</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Les fichiers personnels (<code>PERSONAL_FILE_ROOT</code>, ADR-0017) et les médias (<code>MEDIA_ROOT</code>, ADR-0041) sont rangés sous une clé qui est l&#39;empreinte SHA-256 de l&#39;organisation et de l&#39;identifiant du fichier. Leurs lignes (<code>personal_files</code>, <code>media_assets</code>, <code>media_captions</code>) dépendent de l&#39;organisation par <code>ON DELETE CASCADE</code>.</p><p>Aucune route ne supprime une organisation. Supprimer sa ligne en base efface toutes ses données, mais pas les octets de ses fichiers : la base ne sait pas effacer un fichier. Une fois les lignes parties, plus rien ne désigne ces octets, et le dépôt ne permet pas de les retrouver (il n&#39;offre aucune énumération, ADR-0017). Pour les fichiers personnels, ce sont des données personnelles conservées sans finalité.</p><p>L&#39;audit proposait deux voies : une commande de clôture d&#39;organisation, ou un balayage des orphelins. Le Product Owner retient la commande.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Une commande d&#39;exploitation, pas une route.</strong> <code>python -m app.cli.organization_closure &lt;UUID&gt;</code> (dépôt, conteneur <code>cms-api</code>), ou <code>python -m manage close-organization &lt;UUID&gt;</code> (projet <code>teuthiscms</code>). Elle lit <code>DATABASE_URL</code> et compose le processus comme l&#39;API : les dépôts de fichiers sont ceux de l&#39;instance. Qui peut la lancer peut déjà écrire dans la base : elle ne donne aucun droit nouveau. Aucune route ni aucun bouton ne sont prévus : clôturer une collectivité n&#39;est pas un geste d&#39;agent.</li><li><strong>Un bilan d&#39;abord.</strong> Nom, nombre de sites, de contenus, de soumissions de formulaires, de fichiers personnels, de médias et de sous-titres, et octets sur disque. Des agrégats seulement : aucune ligne n&#39;est chargée.</li><li><strong>Une confirmation explicite.</strong> Il faut retaper le nom exact de l&#39;organisation ou son identifiant. <code>--oui</code> saute la question pour un usage scripté, <strong>seulement avec <code>--nom</code></strong>, qui doit être le nom exact (pas l&#39;identifiant, déjà donné en argument). Une confirmation absente ou fausse n&#39;efface rien.</li><li><strong>Les fichiers, puis la base.</strong> Avant tout effacement, la suppression de la ligne est jouée à blanc dans un point de sauvegarde, puis annulée : une contrainte qui refuserait la cascade (un contenu d&#39;une autre organisation qui désigne l&#39;un de ses sites) arrête la commande avant qu&#39;un seul fichier soit touché. Ensuite, les fichiers personnels, les sous-titres et les médias sont <strong>énumérés par la base</strong>, par lots bornés (500 identifiants, pagination par clé), et leurs octets effacés. Aucune ligne n&#39;est touchée pendant cette étape. Enfin, la ligne de l&#39;organisation est supprimée, en une transaction, et la cascade emporte tout le reste.</li><li><strong>Reprenable et idempotente.</strong> Une commande interrompue entre les fichiers et la base (panne de disque, base injoignable, Ctrl-C) laisse l&#39;organisation entière en base. La relancer énumère de nouveau, efface ce qui reste (effacer un fichier absent n&#39;est pas une erreur), puis supprime la base. L&#39;ordre inverse laisserait des octets que plus rien ne désigne. Une organisation déjà clôturée n&#39;existe plus : la commande la refuse comme une organisation inconnue, avec un code de sortie 1, sans rien toucher.</li><li><strong>Le journal, sans donnée personnelle.</strong> Une ligne structurée par étape, journal <code>teuthis.cloture</code> : <code>cloture_organisation_bilan</code>, <code>cloture_organisation_fichiers_effaces</code>, <code>cloture_organisation_terminee</code>, ou <code>cloture_organisation_refusee</code> / <code>cloture_organisation_interrompue</code>. Elles portent l&#39;identifiant de l&#39;organisation, des nombres et des octets. Ni nom de fichier, ni contenu, ni adresse, ni nom de l&#39;organisation : celui-ci est affiché à l&#39;exploitant, pas conservé. La sortie de la commande reprend le bilan et les nombres effacés.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Balayage périodique des orphelins par l&#39;ordonnanceur, seul</strong></td><td>Il effacerait après coup, sans bilan ni confirmation, ce qu&#39;une clôture doit effacer délibérément. Le Product Owner le garde <strong>en plus</strong>, comme filet pour les suppressions faites hors de l&#39;application : <a href="/teuthis-cms-distribution/developpeurs/adr/0060-balayage-des-fichiers-orphelins">ADR-0060</a>.</td></tr><tr><td><strong>Route d&#39;API ou bouton du back-office</strong></td><td>Décider qui peut effacer une collectivité entière n&#39;est pas une décision d&#39;interface (même raisonnement que les purges, notice §6.3).</td></tr><tr><td><strong>La base d&#39;abord, les fichiers ensuite</strong></td><td>Une interruption entre les deux laisserait des octets que plus rien ne désigne : exactement l&#39;écart à corriger.</td></tr><tr><td><strong>Confirmation par <code>--oui</code> seul</strong></td><td>Un identifiant se recopie d&#39;une ligne voisine. Exiger le nom exact oblige le script à savoir ce qu&#39;il clôture.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Clôturer une organisation efface ses fichiers personnels et ses médias, puis ses données, sans reste.</li><li>Une interruption se rattrape en relançant la même commande.</li><li>Aucune migration, aucune dépendance.</li></ul><p><strong>Négatives</strong></p><ul><li>Une organisation supprimée <strong>hors</strong> de cette commande (commande SQL, restauration partielle) laisse toujours ses octets sur le disque. La notice dit de passer par la commande.</li><li>Une table qui déposerait un jour des octets dans l&#39;un de ces dépôts <strong>doit</strong> être ajoutée à l&#39;énumération de <code>delete_organization_files</code> (<code>app/cli/organization_closure.py</code>), sans quoi ses fichiers resteraient après une clôture.</li><li>Les sauvegardes (ADR-0052) contiennent encore l&#39;organisation et ses fichiers jusqu&#39;à leur rotation (7 jours par défaut).</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Commande <code>python -m app.cli.organization_closure</code> et <code>manage.py close-organization</code>. Preuve : <code>tests/test_cloture_d_une_organisation.py</code>.</li><li>[x] Notice d&#39;exploitation, §6.10.</li></ul>',17)])])}const g=n(a,[["render",i]]);export{m as __pageData,g as default};
